package com.bank.vowelcode;

import java.util.*;
import java.util.logging.*;

public class OnlyVowelsDemo {
    private static final Logger log = Logger.getLogger("VowelCode");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> codes = List.of("AEI", "aei", "AB", "oue", "a1");
        VowelCodeService service = new VowelCodeService();

        List<String> vowelOnly = service.onlyVowels(codes);
        log.info(() -> "Vowel-only codes: " + vowelOnly);
    }
}

// ─── Would be in service/VowelCodeService.java ───
class VowelCodeService {
    // precompiled pattern → compiled once, reused per element
    private static final java.util.regex.Pattern VOWELS =
        java.util.regex.Pattern.compile("[aeiouAEIOU]+");

    List<String> onlyVowels(List<String> codes) {
        return codes.stream()
            .filter(s -> VOWELS.matcher(s).matches())   // whole string is all vowels
            .toList();
    }
}
